let mapObserver;let map,mapMarkers=[],filter='all',query='',selected=null,started=false;const list=root.querySelector('#mm-list'),detail=root.querySelector('#mm-detail'),mobile=matchMedia('(max-width:760px)'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fi').trim();
const visibleAll=()=>projects.filter(p=>(filter==='all'||p.region===filter)&&normalize(query).split(/\s+/).every(term=>normalize([p.service,p.city,p.region].join(' ')).includes(term)));
let userPos=null;
const distKm=p=>{const t=Math.PI/180,dLat=(p.lat-userPos.lat)*t,dLng=(p.lng-userPos.lng)*t,a=Math.sin(dLat/2)**2+Math.cos(userPos.lat*t)*Math.cos(p.lat*t)*Math.sin(dLng/2)**2;return 12742*Math.asin(Math.sqrt(a))};
const kmText=p=>{const d=distKm(p);return ' · '+(d<10?d.toFixed(1).replace('.',','):String(Math.round(d)))+' km'};
function setListTitle(){const t=root.querySelector('#mm-list-title');if(t)t.textContent=userPos?'Kohteet lähelläsi':'Kohteet'}
const visible=()=>{const a=visibleAll();return userPos?a.slice().sort((x,y)=>distKm(x)-distKm(y)):a};
function renderList(){list.replaceChildren();if(!visible().length){const empty=document.createElement('p');empty.className='empty-state';empty.textContent=query.trim()?'Haulla ei löytynyt kohteita. Kokeile toista paikkakuntaa tai palvelua.':'Tälle alueelle ei ole vielä lisätty kohteita.';list.append(empty)}visible().forEach(p=>{const b=document.createElement('button');b.className='item'+(selected===p.id?' selected':'');b.setAttribute('aria-label',p.service+', '+p.city+', näytä kartalla');b.setAttribute('aria-pressed',String(selected===p.id));b.innerHTML=`<span class="list-brush" aria-hidden="true"><span class="brand-brush"></span></span><span><b>${p.service}</b><small>${p.city}${userPos?kmText(p):''}</small></span><span class="arrow" aria-hidden="true"><svg viewBox="0 0 24 24" width="22" height="22"><path d="M6.5 17.5 17.5 6.5M8.5 6.5h9v9" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>`;b.onclick=()=>choose(p);list.append(b)});requestAnimationFrame(updateListScroll)}
const mobileMQ=window.matchMedia('(max-width:760px)');
function updateListScroll(){
 const mobile=mobileMQ.matches;
 const items=Array.from(list.querySelectorAll('.item'));
 const need=mobile?4:5;
 if(items.length>=need){
  const top=items[0].getBoundingClientRect().top;
  const r=items[need-1].getBoundingClientRect();
  const height=Math.ceil(mobile?r.top-top+r.height*0.5:r.bottom-top);
  if(height>0&&list.style.height!==height+'px')list.style.height=height+'px';
 }
 const more=root.querySelector('#mm-more-projects');
 more.hidden=list.scrollHeight<=list.clientHeight+2;
 const track=root.querySelector('#mm-list-scroll-track'),thumb=root.querySelector('#mm-list-scroll-thumb');
 track.hidden=more.hidden;
 const height=list.clientHeight,range=list.scrollHeight-height;
 const thumbHeight=Math.min(height,Math.max(48,height*height/Math.max(1,list.scrollHeight)));
 const fraction=range>0?Math.max(0,Math.min(1,list.scrollTop/range)):0;
 thumb.style.height=thumbHeight+'px';
 thumb.style.transform='translateY('+(fraction*(height-thumbHeight))+'px)';
 const bottom=list.scrollTop+list.clientHeight>=list.scrollHeight-3;
 more.innerHTML=bottom?'Takaisin listan alkuun <span aria-hidden="true">↑</span>':'Selaa lisää kohteita <span aria-hidden="true">↓</span>';
}
list.addEventListener('scroll',updateListScroll,{passive:true});
const listObserver=new ResizeObserver(updateListScroll);listObserver.observe(list);
root.querySelector('#mm-more-projects').onclick=()=>{
 const bottom=list.scrollTop+list.clientHeight>=list.scrollHeight-3;
 list.scrollTo({top:bottom?0:list.scrollTop+list.clientHeight,behavior:reduced.matches?'instant':'smooth'});
};
