function fit(animate=true){if(!map)return;if(query.trim()&&visible().length){const bounds=new maplibregl.LngLatBounds();visible().forEach(p=>bounds.extend([p.lng,p.lat]));map.fitBounds(bounds,{padding:65,maxZoom:10,duration:animate&&!reduced.matches?600:0});return;}map.fitBounds(filter==='all'?[[21.0,59.65],[27.1,61.8]]:regionBounds[filter],{padding:{top:60,bottom:35,left:28,right:50},maxZoom:9,duration:animate&&!reduced.matches?600:0})}
function markers(){
 if(!map)return;
 mapMarkers.forEach(m=>m.remove());mapMarkers=[];
 const close=map.getZoom()>=9;
 visible().forEach(p=>{
  const el=document.createElement('button');el.type='button';
  el.className='map-marker single'+(close?' close-up':'');
  el.setAttribute('aria-label',p.service+', '+p.city);
  el.innerHTML='<span class="pin"><span class="brand-brush" aria-hidden="true"></span></span>';
  el.onclick=()=>choose(p);
  mapMarkers.push(new maplibregl.Marker({element:el,anchor:'center'}).setLngLat([p.lng,p.lat]).addTo(map));
 });
}

root.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{filter=b.dataset.region;closeDetail();root.querySelectorAll('[data-region]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});fit();markers()});root.querySelector('#mm-reset').onclick=clearSearch;root.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});

const searchInput=root.querySelector('#mm-project-search');
root.querySelector('#mm-clear-search').onclick=()=>{clearSearch();searchInput.focus()};
function searchProjects(){query=searchInput.value;root.querySelector('#mm-clear-search').hidden=!query.length;list.scrollTop=0;filter='all';root.querySelectorAll('[data-region]').forEach(b=>{const active=b.dataset.region==='all';b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});closeDetail();markers()}
