function refresh(){
 queued=false;
 for(const [root,instance] of mounted){if(!root.isConnected||root.querySelector('#mm-map')!==instance.node){instance.dispose();mounted.delete(root)}}
 document.querySelectorAll('#mm-kohdekartta').forEach(root=>{
  root.querySelectorAll('.mm-catalog').forEach(node=>node.remove());
  const node=root.querySelector('#mm-map');
  if(!mounted.has(root)&&node&&root.querySelector('#mm-list')&&root.querySelector('#mm-locate')){
   mounted.set(root,{node,dispose:start(root)});
  }
 });
}
const observer=new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(refresh)}});
